sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    //  if(!g_form.isLiveUpdating()){



    var dynamic_query = g_scratchpad.query;
    var rows = g_scratchpad.rows;
    var host = g_scratchpad.host;
	var listID = g_scratchpad.listID;//MSSOTIQUBE-1402
    var assign = g_form.getValue('assigned_to');
    var stat = g_form.getValue('state');

    if ((newValue == 'false') && (assign == "") && (stat == 1)) {
        var ans = confirm('Due to the inactivity, the current task is unlocked and unassigned');

        // if confirm or cancel user is redirected to list view
        if (ans) {
            var currentUrl = top.location.href; //MSSOTIQUBE-1402
			if (currentUrl.indexOf('workspace') > -1) {
            var url = host + '/x/hsb11/mss-custody-workspace/list/params/list-id/' + listID;
            top.window.location = url;
			}
			else{
            var url2 = host + '/x_hsb11_mss_c_proc_mss_custody_task_list.do?&sysparm_query=' + dynamic_query;
            top.window.location = url2;
			}
        } 

    }

}
